export function normalizeRoleProfile(profile={},base=DEFAULT_PROFILE){
  const merged={...base,...profile,geography:{...(base.geography||{}),...(profile.geography||{})},compensation:{...(base.compensation||{}),...(profile.compensation||{})},weights:{...(base.weights||{}),...(profile.weights||{})}};
  const array=(value,name)=>{if(!Array.isArray(value)||value.some(x=>typeof x!=="string"||!x.trim()))throw new Error(`invalid_profile_${name}`);return[...new Set(value.map(x=>x.trim()))]};
  merged.id=String(merged.id||"default").trim();
  merged.name=String(merged.name||"").trim();
  if(!/^[a-z0-9][a-z0-9_-]{0,63}$/i.test(merged.id)||!merged.name||merged.name.length>120)throw new Error("invalid_profile_identity");
  merged.aliases=array(merged.aliases,"aliases");merged.exclusions=array(merged.exclusions,"exclusions");merged.engagement_types=array(merged.engagement_types,"engagement_types");
  merged.geography={remote:merged.geography.remote===true,relocation:merged.geography.relocation===true,commuting:array(merged.geography.commuting||[],"commuting"),negotiated:array(merged.geography.negotiated||[],"negotiated")};
  merged.compensation={...merged.compensation,full_time_base_floor:Number(merged.compensation.full_time_base_floor),contract_hourly_floor:Number(merged.compensation.contract_hourly_floor),board_requires_manual_review:merged.compensation.board_requires_manual_review!==false};
  merged.review_threshold=Number(merged.review_threshold);
  if(!Number.isFinite(merged.compensation.full_time_base_floor)||merged.compensation.full_time_base_floor<0||!Number.isFinite(merged.compensation.contract_hourly_floor)||merged.compensation.contract_hourly_floor<0||!Number.isFinite(merged.review_threshold)||merged.review_threshold<0||merged.review_threshold>100)throw new Error("invalid_profile_threshold");
  return merged;
}

export function normalizeUrl(value) {
  if (!value) return null;
  try {
    const u = new URL(value);
    if(!["http:","https:"].includes(u.protocol))return null;
    ["utm_source","utm_medium","utm_campaign","utm_term","utm_content","trk","trackingId"].forEach(k => u.searchParams.delete(k));
    u.hash = "";
    return u.toString().replace(/\/$/, "");
  } catch { return null; }
}

const TRACKING_QUERY_KEYS = new Set(["utm_source","utm_medium","utm_campaign","utm_term","utm_content","trk","trackingId","refId","lipi","midToken","midSig","trkEmail","eid","otpToken","imp_id","origin","originToLandingJobPostings"]);
export function normalizeResearchUrl(value, source, kind="listing") {
  const normalized=normalizeUrl(value);
  if(!normalized)return null;
  const u=new URL(normalized),host=u.hostname.toLowerCase(),path=u.pathname.replace(/\/{2,}/g,"/");
  for(const key of [...u.searchParams.keys()])if(TRACKING_QUERY_KEYS.has(key)||/^utm_/i.test(key))u.searchParams.delete(key);
  if(source==="linkedin"||host.endsWith("linkedin.com")){
    const job=path.match(/\/jobs\/view\/(\d+)/);
    if(job)return `https://www.linkedin.com/jobs/view/${job[1]}`;
    if(/\/jobs\/search-results\/?$/.test(path)){for(const key of [...u.searchParams.keys()])if(!["keywords","distance","f_TPR","geoId"].includes(key))u.searchParams.delete(key);}
  }
  if(source==="jobright"||host.endsWith("jobright.ai")){
    const job=path.match(/\/jobs\/info\/([a-z0-9]+)/i);
    if(job)return `https://jobright.ai/jobs/info/${job[1]}`;
  }
  if(source==="indeed"||host.endsWith("indeed.com")){
    const jk=u.searchParams.get("jk");
    if(jk&&(/\/viewjob\/?$/.test(path)||/\/rc\/clk\/?$/.test(path)))return `https://${host}/viewjob?jk=${encodeURIComponent(jk)}`;
  }
  u.pathname=path;
  u.hash="";
  return u.toString().replace(/\/$/,"");
}

export async function sha256(value) {
  const bytes = new TextEncoder().encode(value);
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return [...new Uint8Array(digest)].map(b => b.toString(16).padStart(2, "0")).join("");
}
export async function sha256Bytes(value) {
  const bytes=value instanceof Uint8Array?value:new Uint8Array(value);
  const digest=await crypto.subtle.digest("SHA-256",bytes);
  return[...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,"0")).join("");
}

export async function canonicalJobId(card) {
  const stableUrl = normalizeUrl(card.listing_url);
  const identity = card.external_id ? `${card.source}|external|${card.external_id}` : stableUrl ? `${card.source}|url|${stableUrl}` : [card.source, card.title, card.company, card.location].map(v => String(v || "").trim().toLowerCase()).join("|");
  return `job_${(await sha256(identity)).slice(0, 24)}`;
}

export function classifyLink(href, text = "", source = "") {
  const url = normalizeUrl(href);
  if (!url) return { kind: "ignore", url: null };
  const u=new URL(url),host=u.hostname.toLowerCase(),path=u.pathname.toLowerCase(),anchorText = String(text).replace(/&(?:nbsp|#8203);/gi," ").trim().toLowerCase(),provider=source||host.split(".").slice(-2,-1)[0];
  const navigationText=/^(?:unsubscribe(?:\s+from\s+(?:these\s+)?emails?)?|preferences?|privacy(?:\s+policy)?|manage (?:job )?alerts?|update job alert preferences?|help|support|sign in|log in|my network|messaging|terms(?:(?:\s*&\s*|\s+and\s+)conditions|\s+of\s+(?:use|service))?|contact(?:\s+us)?|facebook group|find jobs now|(?:facebook|linkedin|instagram|twitter|x)|(?:visit|follow|find|connect with)\s+(?:us|ladders)\s+on\s+(?:facebook|linkedin|instagram|twitter|x))$/;
  if(navigationText.test(anchorText)||/unsubscribe|preferences|privacy|\/help(?:[/?#]|$)|\/support(?:[/?#]|$)|\/feed\/?$|\/messaging\/?$|\/mynetwork\/?$|\/jobs\/alerts\/?$/.test(`${path}${u.search}`))return{kind:"navigation",url};
  if(provider==="jobright"||host.endsWith("jobright.ai")){
    if(/^\/jobs\/info\/[a-z0-9]+\/?$/i.test(path))return{kind:"listing",url:normalizeResearchUrl(url,"jobright","listing")};
    if(/^\/jobs\/recommend\/?$/.test(path))return{kind:"discovery",url:normalizeResearchUrl(url,"jobright","discovery")};
    return{kind:"navigation",url};
  }
  if(provider==="linkedin"||host.endsWith("linkedin.com")){
    if(/\/jobs\/view\/\d+\/?$/.test(path))return{kind:"listing",url:normalizeResearchUrl(url,"linkedin","listing")};
    if(/\/jobs\/search-results\/?$/.test(path))return{kind:"discovery",url:normalizeResearchUrl(url,"linkedin","discovery")};
    return{kind:"navigation",url};
  }
  if(provider==="indeed"||host.endsWith("indeed.com")){
    if((/\/viewjob\/?$/.test(path)||/\/rc\/clk\/?$/.test(path))&&u.searchParams.get("jk"))return{kind:"listing",url:normalizeResearchUrl(url,"indeed","listing")};
    if(/\/jobs\/?$|\/jobs\/search/.test(path)||/see[-_ ]?all|view[-_ ]?all|search jobs/.test(anchorText))return{kind:"discovery",url:normalizeResearchUrl(url,"indeed","discovery")};
  }
  if(provider==="ladders"||host.endsWith("ladders.com")||host==="t.ladders.co"){
    if(host==="facebook.com"||host.endsWith(".facebook.com"))return{kind:"navigation",url};
    if(navigationText.test(anchorText)||/^(?:remote|\$[\d,]+(?:\s*-\s*\$[\d,]+)?\*?|ladders, inc\.)$/.test(anchorText))return{kind:"navigation",url};
    if(host==="t.ladders.co"&&path.startsWith("/f/a/"))return{kind:"candidate",url:normalizeResearchUrl(url,"ladders","listing")};
  }
  const urlText=url.toLowerCase();
  if (/see[-_ ]?all|view[-_ ]?all|search(?:[/?#]|$)|jobs\/collections|jobsearch/.test(`${urlText} ${anchorText}`)) return { kind: "discovery", url:normalizeResearchUrl(url,provider,"discovery") };
  if (/\/jobs\/view\/|viewjob|job-details|jobdetail|job-posting|~[0-9a-f]{8,}/.test(urlText)) return { kind: "listing", url:normalizeResearchUrl(url,provider,"listing") };
  return { kind: "candidate", url:normalizeResearchUrl(url,provider,"listing") };
}

export function extractLinks(html, baseUrl, source) {
  const links = [];
  const re = /<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
  for (const m of html.matchAll(re)) {
    let href;
    try { href = new URL(m[1].replace(/&amp;/g, "&"), baseUrl).toString(); } catch { continue; }
    const text = m[2].replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
    const classified = classifyLink(href, text, source);
    if (classified.kind !== "ignore") links.push({ source, text, ...classified, parser_version: PARSER_VERSION });
  }
  return links;
}

export function paginate(listPage, fetchPage, onPage = () => {}) {
  return (async function* () {
    let token = null;
    do {
      const page = await fetchPage(token);
      onPage(page);
      for (const item of page.items || page.messages || []) yield item;
      token = page.nextPageToken || null;
    } while (token);
  })();
}

export function scoreJob(job, profile = DEFAULT_PROFILE, arsenal = { claims: [] }) {
  const title = String(job.title || "").toLowerCase(), text = `${title} ${job.full_description || job.description || ""}`.toLowerCase();
  const hasTerm=(haystack,term)=>{const escaped=String(term||"").trim().toLowerCase().replace(/[.*+?^${}()|[\]\\]/g,"\\$&");return!!escaped&&new RegExp(`(^|[^a-z0-9])${escaped}(?=$|[^a-z0-9])`).test(haystack)};
  const aliasHits = profile.aliases.filter(x => hasTerm(title,x));
  const exclusions = profile.exclusions.filter(x => hasTerm(title,x));
  const evidence = (arsenal.claims || []).filter(c => (c.tags || []).some(t => hasTerm(text,t)));
  let score = Math.min(profile.weights.title, aliasHits.length * 14) + Math.min(profile.weights.evidence, evidence.length * 5);
  const locationText = `${job.location || ""} ${text}`.toLowerCase();
  const remote = /remote|telecommut/.test(locationText);
  const commuting = (profile.geography?.commuting || []).some(x => locationText.includes(x.toLowerCase()));
  const negotiated = (profile.geography?.negotiated || []).some(x => locationText.includes(x.toLowerCase()));
  const relocationRequired = /must relocate|relocation required|required to relocate/.test(locationText);
  if ((remote && profile.geography?.remote === true) || commuting) score += profile.weights.geography;
  const isBoard = /board|director|trustee/.test(job.engagement_type || "") || /board member|board director|independent director|trustee/.test(text);
  let compensation = "unknown";
  if (isBoard) compensation = "manual_review";
  else if (job.salary_min != null) { compensation = job.salary_min >= profile.compensation.full_time_base_floor ? "meets" : "below"; score += compensation === "meets" ? profile.weights.compensation : 0; }
  else if (job.hourly_min != null) { compensation = job.hourly_min >= profile.compensation.contract_hourly_floor ? "meets" : "below"; score += compensation === "meets" ? profile.weights.compensation : 0; }
  const rawEngagement = String(job.engagement_type || "").toLowerCase().replace(/[ -]+/g, "_");
  const engagement = !rawEngagement ? "unknown" : (profile.engagement_types || []).some(x => rawEngagement.includes(String(x).toLowerCase())) ? "meets" : "outside_profile";
  const geography = relocationRequired && profile.geography?.relocation === false ? "blocked_relocation" : remote && profile.geography?.remote !== true ? "blocked_remote" : remote || commuting ? "meets" : negotiated ? "manual_review" : "unknown";
  const vetoes = [...exclusions.map(x => `excluded:${x}`)];
  if (compensation === "below") vetoes.push("compensation_below_floor");
  if (engagement === "outside_profile") vetoes.push("engagement_outside_profile");
  if (geography === "blocked_relocation") vetoes.push("relocation_not_allowed");
  if (geography === "blocked_remote") vetoes.push("remote_not_allowed");
  const reviewReasons = [];
  if (compensation === "unknown" || compensation === "manual_review") reviewReasons.push(`compensation_${compensation}`);
  if (engagement === "unknown") reviewReasons.push("engagement_unknown");
  if (geography === "unknown" || geography === "manual_review") reviewReasons.push(`geography_${geography}`);
  // Generic leadership/architecture overlap is not evidence of a mandatory
  // specialist qualification. Missing evidence creates a review gap only; it
  // never asserts that the candidate lacks the qualification.
  const specialistRules = [
    ["statistical_programming", /statistical programming|biometrics/i, /statistical programming|biometrics/i],
    ["sas_programming", /(?:expert|proficien\w*|required)[^.!?\n]{0,80}\bsas\b|\bsas\/base\b/i, /\bsas\b|sas programming/i],
    ["clinical_regulatory_submissions", /(?:clinical development|regulatory submissions?|\bBLA\b|\bIND\b|health authority submissions?)/i, /clinical development|regulatory submissions?|\bBLA\b|\bIND\b/i],
    ["clinical_data_standards", /\b(?:CDISC|SDTM|ADaM|CDASH|MedDRA|WHODrug)\b/i, /\b(?:CDISC|SDTM|ADaM|CDASH|MedDRA|WHODrug)\b/i],
    ["insurance_industry", /deep insurance industry experience|insurance industry experience[^.!?\n]{0,30}(?:required|must)/i, /insurance industry|insurance architecture/i],
    ["claims_domain", /claims experience[^.!?\n]{0,30}(?:required|strongly preferred)|(?:required|must)[^.!?\n]{0,50}claims experience/i, /claims experience|insurance claims/i],
    ["actuarial_credentials", /\b(?:FSA|FCAS|ASA|ACAS)\b|credentialed actuary|actuarial credentials?/i, /\b(?:FSA|FCAS|ASA|ACAS)\b|actuarial/i],
    ["legal_credentials", /\bJ\. ?D\.\b|active bar (?:membership|admission)|licensed attorney/i, /\bJ\. ?D\.\b|bar admission|licensed attorney/i],
    ["accounting_credentials", /\bCPA\b[^.!?\n]{0,30}(?:required|preferred)|certified public accountant/i, /\bCPA\b|certified public accountant/i]
  ];
  const matchedTagText=evidence.flatMap(c=>c.tags||[]).join(" ");
  const mandatorySpecialistGaps=specialistRules.filter(([,listingPattern,supportPattern])=>listingPattern.test(text)&&!supportPattern.test(matchedTagText)).map(([name])=>name);
  for(const gap of mandatorySpecialistGaps)reviewReasons.push(`mandatory_specialist_unverified:${gap}`);
  score = Math.max(0, Math.min(100, score - exclusions.length * 35));
  const band = vetoes.length ? "blocked" : reviewReasons.length ? "review" : score >= 70 ? "strong" : score >= profile.review_threshold ? "review" : "low";
  return { assessment_method_version:ASSESSMENT_METHOD_VERSION, score, band, alias_hits: aliasHits, exclusion_hits: exclusions, compensation, mandatory_specialist_gaps:mandatorySpecialistGaps, hard_constraints: { compensation, engagement, geography, vetoes, review_reasons: reviewReasons }, arsenal_matches: evidence.map(x => ({ claim_id: x.id, source_anchor: x.source_anchor, tags: x.tags })) };
}

export async function makeResearchTasks(observation) {
  const actionable=observation.links.map((link,i)=>({link,i})).filter(({link})=>["listing","discovery","candidate"].includes(link.kind));
  return Promise.all(actionable.map(async({link,i}) => ({
    id: `research_${(await sha256(`${link.source}|${link.kind==="discovery"?"walk_discovery":"fetch_listing"}|${link.url}`)).slice(0,32)}`,
    observation_ordinal:i,
    message_id: observation.message_id,
    source: link.source,
    url: link.url,
    task_kind: link.kind === "discovery" ? "walk_discovery" : "fetch_listing",
    classification: link.kind,
    status: "pending",
    attempts: 0
  })));
}

export function cleanupEligibility(message, tasks, reconciliation) {
  const protectedThread = message.is_human_thread || message.has_application_signal || message.has_interview_signal || !message.is_job_newsletter;
  if (protectedThread) return { eligible: false, reason: "protected_message" };
  if (!reconciliation.committed || !reconciliation.readback_ok) return { eligible: false, reason: "commit_not_verified" };
  if (!Number.isInteger(reconciliation.discovered_cards) || !Number.isInteger(reconciliation.persisted_observations) || reconciliation.discovered_cards < 0 || reconciliation.persisted_observations < 0) return { eligible: false, reason: "counts_unverified" };
  if (reconciliation.discovered_cards !== reconciliation.persisted_observations) return { eligible: false, reason: "count_mismatch" };
  if (reconciliation.discovered_cards === 0 && !reconciliation.explicit_empty_newsletter) return { eligible: false, reason: "empty_unverified" };
  if (reconciliation.discovered_cards > 0 && tasks.length === 0) return { eligible: false, reason: "tasks_missing" };
  if (tasks.some(t => !["complete", "not_a_listing"].includes(t.status))) return { eligible: false, reason: "research_incomplete" };
  return { eligible: true, reason: "preview_only" };
}

export function redact(value) {
  return String(value).replace(/(authorization:\s*bearer\s+)[^\s]+/ig, "$1[REDACTED]").replace(/((?:access|refresh|id)_token["'=:\s]+)[^\s,"'}]+/ig, "$1[REDACTED]").replace(/(client_secret["'=:\s]+)[^\s,"'}]+/ig, "$1[REDACTED]");
}

export async function ingestMailbox({ gmail, repo, mailbox = EXPECTED_MAILBOX, arsenalVersion }) {
  const actual = await gmail.profile();
  if (String(actual.emailAddress).toLowerCase() !== mailbox.toLowerCase()) throw new Error("mailbox_account_mismatch");
  const run = await repo.beginRun({ kind: "gmail_intake", arsenalVersion });
  let pages = 0, messages = 0, observations = 0;
  for await (const summary of paginate(null, token => gmail.listMessages({ pageToken: token, maxResults: 100 }),()=>{pages++})) {
    if (await repo.messageComplete(summary.id)) continue;
    const message = await gmail.getMessage(summary.id);
    if (!message.is_verified_job_alert) continue;
    const threadContext = gmail.getThreadContext ? await gmail.getThreadContext(message.thread_id) : {};
    Object.assign(message,{is_human_thread:message.is_human_thread||!!threadContext.is_human_thread,has_application_signal:message.has_application_signal||!!threadContext.has_application_signal,has_interview_signal:message.has_interview_signal||!!threadContext.has_interview_signal});
    messages++;
    const links = extractLinks(message.html || "", message.base_url || "https://mail.google.com", message.source);
    const obs = { message_id: summary.id, source: message.source, received_at: message.received_at, card_count: message.card_count ?? links.filter(x => x.kind === "listing").length, links };
    const tasks = await makeResearchTasks(obs);
    await repo.atomicCommitMessage({ message, observation: obs, tasks });
    const check = await repo.readbackMessage(summary.id);
    if (!check.committed || check.task_count !== tasks.length) throw new Error(`message_readback_failed:${summary.id}`);
    observations++;
  }
  await repo.finishRun(run.id, { status: "complete", pages, messages, observations });
  return { run_id: run.id, pages, messages, observations };
}

export function parseIntakeBounds({max_messages,window_hours}={}){
  const parse=(value,fallback,name,cap)=>{if(value===undefined||value===null||value==="")return fallback;if(!/^\d+$/.test(String(value)))throw new Error(`invalid_${name}`);const n=Number(value);if(!Number.isSafeInteger(n)||n<1||n>cap)throw new Error(`invalid_${name}`);return n};
  return{max_messages:parse(max_messages,5,"max_messages",5),window_hours:parse(window_hours,24,"window_hours",24)};
}

export function isProtectedCatchupSubject(message){
  const subject=String(message?.subject||"").toLowerCase(),source=String(message?.source||"");
  const protectedTemplate=/^(?:your application(?: (?:has been )?(?:received|submitted|viewed)| was sent| update)?|your job alert (?:was )?created|do you still want to hear from us|turbo welcome|new messages? for you|(?:the )?ladders (?:browser )?extension|apply4me|(?:ladders )?resume (?:review|rewrite|service|update)|premium membership|(?:daily )?motivation|(?:your )?(?:linkedin |ladders |indeed |flexjobs )?account (?:activation|confirmation|notice|security|setup|verification|welcome))(?:\s*(?:[!?:]|[-\u2014]).*)?$/;
  if(protectedTemplate.test(subject))return true;
  if(source==="linkedin"&&(/^[^,]{1,80},\s+your application was sent to\s+.+$/.test(subject)||/^your application to\s+.+$/.test(subject)||/^[^:]{1,80}:\s+your job alert for\s+.+\s+has been created[.!]?$/.test(subject)))return true;
  if(source==="flexjobs"&&/^new messages? for you @ flexjobs!$/.test(subject))return true;
  if(source==="jobright"&&/^welcome to turbo! let[’']s land jobs together\s*🚀$/.test(subject))return true;
  return false;
}

export function classifyCatchupBody(message,links){
  const actionable=(links||[]).filter(x=>x.kind==="listing"||x.kind==="discovery");
  if(actionable.length)return{accept:true,reason_code:"verified_job_content"};
  if((links||[]).some(x=>x.kind==="candidate"))return{accept:true,reason_code:"job_content_uncertain",quarantine:true};
  return{accept:false,reason_code:"no_job_content"};
}

function protectedMessageSignals(source,subject){
  const protectedSubject=isProtectedCatchupSubject({source,subject});
  return{
    has_application_signal:protectedSubject&&/\b(?:application|applied|candidate)\b/i.test(subject),
    has_interview_signal:/^(?:your\s+)?interview\s+(?:invitation|request|scheduled|confirmed|confirmation)\b|^interview\s+(?:invitation|request|scheduled|confirmation)\b/i.test(subject)
  };
}

export function classifyThreadContextMessages(messages=[]){
  const rows=messages.map(x=>{const from=gmailHeader(x.payload,"From"),subject=gmailHeader(x.payload,"Subject"),auth=gmailHeader(x.payload,"Authentication-Results"),verified=classifyAlertSender(from,auth,subject),signals=verified.ok?protectedMessageSignals(verified.source,subject):{has_application_signal:false,has_interview_signal:false};return{from,subject,verified,...signals}});
  const human=rows.some(x=>!x.verified.ok&&!/ctiberius@gmail\.com/i.test(x.from));
  const application=rows.some(x=>x.has_application_signal),interview=rows.some(x=>x.has_interview_signal);
  return{is_human_thread:human,has_application_signal:application,has_interview_signal:interview};
}

