export async function researchOne({ task, provider, repo }) {
  try {
    const result = await provider.fetch(task);
    if (task.task_kind === "walk_discovery") {
      if (!result?.discovery_complete || !Array.isArray(result.discovered_tasks)) {
        if (Array.isArray(result?.discovered_tasks) && result.discovered_tasks.length && repo.checkpointDiscovery) return repo.checkpointDiscovery(task,result);
        const status=["login_required","blocked","incomplete_retry"].includes(result?.status)?result.status:"incomplete_retry";
        return repo.updateTask(task.id,{status,error_code:result?.error_code||"discovery_not_exhausted"});
      }
      return repo.commitDiscovery(task,result.discovered_tasks);
    }
    if (!result?.full_description) return repo.updateTask(task.id, { status: ["login_required","blocked","incomplete_retry","not_a_listing"].includes(result?.status) ? result.status : "incomplete_retry", error_code: result?.error_code || "missing_full_listing" });
    if (!Array.isArray(result.evidence) || !result.evidence.some(e => e?.claim_text && e?.source_url)) return repo.updateTask(task.id,{status:"incomplete_retry",error_code:"listing_evidence_missing"});
    const id = await canonicalJobId({ ...result, source: task.source, listing_url: task.url });
    return repo.commitResearch({ task, canonical_job_id: id, listing: result, evidence: result.evidence || [] });
  } catch (error) {
    const status = /login|401|403/i.test(String(error.message || error)) ? "login_required" : "incomplete_retry";
    return repo.updateTask(task.id, { status, error_code: redact(error.message || error) });
  }
}

