export async function materializeArtifactToDrive(env,artifactId,folderId){if(!env?.DB?.prepare||!env?.DRIVE_ARTIFACT_CONNECTOR?.fetch)throw new Error("drive_artifact_binding_required");const row=await env.DB.prepare("SELECT a.id,a.artifact_type,a.content_hash,d.content,d.revision FROM application_artifacts a JOIN application_document_revisions d ON d.id=a.source_document_revision_id WHERE a.id=? AND a.status='draft'").bind(artifactId).first();if(!row)throw new Error("drive_artifact_source_not_found");const bytes=renderDocxDocument(row.content),connector={createFile:async value=>{const response=await env.DRIVE_ARTIFACT_CONNECTOR.fetch(new Request("https://drive-artifact-connector/create",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({...value,bytes:[...value.bytes]})}));if(!response.ok)throw new Error("drive_artifact_create_failed");return response.json()},readFile:async id=>{const response=await env.DRIVE_ARTIFACT_CONNECTOR.fetch(`https://drive-artifact-connector/read/${encodeURIComponent(id)}`);if(!response.ok)throw new Error("drive_artifact_readback_failed");const value=await response.json();return{...value,bytes:new Uint8Array(value.bytes)}}},verified=await createAndVerifyDriveArtifact({artifact_id:row.id,file_name:`${row.artifact_type}-r${row.revision}.docx`,mime_type:"application/vnd.openxmlformats-officedocument.wordprocessingml.document",bytes,folder_id:folderId},{connector});if(verified.content_hash!==String(row.content_hash).toLowerCase())throw new Error("drive_artifact_source_hash_mismatch");const now=isoNow(),receiptHash=await sha256(JSON.stringify(verified));await env.DB.batch([env.DB.prepare("UPDATE application_artifacts SET drive_file_id=? WHERE id=? AND drive_file_id IS NULL").bind(verified.drive_file_id,row.id),env.DB.prepare("INSERT INTO artifact_verifications(artifact_id,drive_file_id,content_hash,byte_size,drive_modified_time,verification_source,receipt_hash,verified_at) VALUES(?,?,?,?,?,'trusted_connector_receipt',?,?)").bind(row.id,verified.drive_file_id,verified.content_hash,verified.byte_size,verified.drive_modified_time,receiptHash,now),env.DB.prepare("INSERT INTO audit(id,occurred_at,actor,action,object_type,object_id,detail_json) VALUES(?,?,?,?,?,?,?)").bind(uuid("audit"),now,"trusted_drive_connector","artifact_created_and_verified","application_artifact",row.id,JSON.stringify({...verified,receipt_hash:receiptHash}))]);return{...verified,receipt_hash:receiptHash,verified_at:now}}
function evidenceSources(value){if(!Array.isArray(value)||!value.length)throw new Error("evidence_sources_required");return value.map((x,i)=>{let source_url;try{source_url=new URL(String(x?.source_url||"")).toString()}catch{throw new Error(`invalid_evidence_source:${i}`)}if(!/^https?:/.test(source_url)||!String(x?.claim_text||"").trim())throw new Error(`invalid_evidence_source:${i}`);return{source_url,source_title:String(x.source_title||"").trim()||null,claim_text:String(x.claim_text).trim()}})}
