export function validateAuthenticatedListingCapture(value,nowMs=Date.now()){if(!plainObject(value)||!exactKeys(value,["job_id","source_url","captured_at","availability","full_description","title","company","location","engagement_type","external_id"]))throw new Error("invalid_authenticated_capture_shape");const job_id=String(value.job_id||"").trim(),source_url=normalizeUrl(value.source_url),captured_at=String(value.captured_at||"").trim(),availability=String(value.availability||"").trim(),capturedMs=Date.parse(captured_at);if(!job_id||!source_url||!['open','closed','inaccessible'].includes(availability)||!Number.isFinite(capturedMs)||capturedMs>nowMs+60_000||capturedMs<nowMs-5*60_000)throw new Error("invalid_authenticated_capture");const full_description=String(value.full_description||"").trim();if(availability==='open'&&!full_description)throw new Error("open_listing_description_required");if(availability!=='open'&&full_description)throw new Error("unavailable_listing_must_not_include_description");return{job_id,source_url,captured_at:new Date(capturedMs).toISOString(),availability,full_description,title:String(value.title||"").trim()||null,company:String(value.company||"").trim()||null,location:String(value.location||"").trim()||null,engagement_type:String(value.engagement_type||"").trim()||null,external_id:String(value.external_id||"").trim()||null}}

