  async listJobs({limit=100,status}={}) { let sql="SELECT j.*,(SELECT t.status FROM research_tasks t WHERE t.canonical_job_id=j.id ORDER BY t.updated_at DESC,t.id DESC LIMIT 1) research_status,(SELECT COUNT(*) FROM evidence e WHERE e.canonical_job_id=j.id) evidence_count FROM canonical_jobs j WHERE j.id<>'fixture-job-001'"; const binds=[];
    if(status){sql+=" AND EXISTS(SELECT 1 FROM research_tasks ts WHERE ts.canonical_job_id=j.id AND ts.status=?)";binds.push(status)} sql+=" ORDER BY j.last_seen_at DESC LIMIT ?";binds.push(Math.min(250,Math.max(1,Number(limit)||100)));
    return (await this.db.prepare(sql).bind(...binds).all()).results||[]; }
  async listQueue({limit=50,offset=0,status}={}) { let sql="SELECT id,observation_id,source,task_kind,url,status,attempts,error_code,canonical_job_id,updated_at FROM research_tasks WHERE superseded_by_task_id IS NULL",binds=[];if(status){sql+=" AND status=?";binds.push(status)}sql+=" ORDER BY CASE status WHEN 'login_required' THEN 0 WHEN 'blocked' THEN 1 WHEN 'incomplete_retry' THEN 2 ELSE 3 END,updated_at DESC LIMIT ? OFFSET ?";binds.push(Math.min(100,Math.max(1,Number(limit)||50)),Math.max(0,Number(offset)||0));return (await this.db.prepare(sql).bind(...binds).all()).results||[]; }
  async retryTask(id){const row=await this.db.prepare("SELECT status,attempts,error_code FROM research_tasks WHERE id=?").bind(id).first();if(!row)throw new Error("task_not_found");if(!["login_required","blocked","incomplete_retry"].includes(row.status))throw new Error("task_not_recoverable");const prior=await this.db.prepare("SELECT COUNT(*) n FROM audit WHERE object_type='research_task' AND object_id=? AND action='manual_retry_budget_reset'").bind(id).first(),generation=Number(prior?.n||0)+1,now=isoNow(),detail={generation,previous_status:row.status,previous_attempts:Number(row.attempts||0),previous_error_code:row.error_code||null,new_attempt_budget:5};await this.db.batch([this.db.prepare("UPDATE research_tasks SET status='pending',attempts=0,error_code=NULL,next_attempt_at=NULL,updated_at=? WHERE id=?").bind(now,id),this.db.prepare("INSERT INTO audit(id,occurred_at,actor,action,object_type,object_id,detail_json) VALUES(?,?,?,?,?,?,?)").bind(uuid("audit"),now,"dashboard_user","manual_retry_budget_reset","research_task",id,JSON.stringify(detail))]);return{id,status:"pending",attempts:0,retry_generation:generation}}
  async listRunnableTasks({limit=10,afterId="",source=null}={}){const selected=source===null?null:String(source).toLowerCase();if(selected!==null&&!PUBLIC_SOURCE_CONFIG[selected])throw new Error("invalid_research_source");const sourceClause=selected?" AND t.source=?":"",binds=[isoNow(),afterId];if(selected)binds.push(selected);binds.push(Math.min(50,Math.max(1,Number(limit)||10)));const rows=(await this.db.prepare(`SELECT t.id,t.observation_id,t.source,t.task_kind,t.url,t.status,t.attempts,t.error_code,t.updated_at,c.state_json checkpoint_json FROM research_tasks t LEFT JOIN research_checkpoints c ON c.task_id=t.id WHERE t.superseded_by_task_id IS NULL AND t.status IN ('pending','incomplete_retry') AND t.attempts<5 AND (t.next_attempt_at IS NULL OR t.next_attempt_at<=?) AND t.id>?${sourceClause} ORDER BY t.updated_at ASC,t.id ASC LIMIT ?`).bind(...binds).all()).results||[];return rows.map(x=>({...x,checkpoint:x.checkpoint_json?JSON.parse(x.checkpoint_json):null}));}
  async claimRunnableListingTask(id){const taskId=String(id||"");if(!/^research_[a-f0-9]{32}$/.test(taskId))throw new Error("invalid_research_task_id");const before=await this.db.prepare("SELECT id,task_kind,status,attempts,superseded_by_task_id,next_attempt_at FROM research_tasks WHERE id=?").bind(taskId).first();if(!before)throw new Error("task_not_found");if(before.task_kind!=="fetch_listing")throw new Error("task_not_listing");if(before.superseded_by_task_id)throw new Error("task_superseded");if(before.status==="running")throw new Error("task_already_running");if(before.status!=="pending"||Number(before.attempts)>=5||(before.next_attempt_at&&before.next_attempt_at>isoNow()))throw new Error("task_not_runnable");const now=isoNow(),claimed=await this.db.prepare("UPDATE research_tasks SET status='running',updated_at=? WHERE id=? AND superseded_by_task_id IS NULL AND task_kind='fetch_listing' AND status='pending' AND attempts<5 AND (next_attempt_at IS NULL OR next_attempt_at<=?)").bind(now,taskId,now).run();if(Number(claimed?.meta?.changes??claimed?.changes??0)!==1){const current=await this.db.prepare("SELECT status FROM research_tasks WHERE id=?").bind(taskId).first();throw new Error(current?.status==="running"?"task_already_running":"task_not_runnable")}const row=await this.db.prepare("SELECT t.id,t.observation_id,t.source,t.task_kind,t.url,t.status,t.attempts,t.error_code,t.updated_at,c.state_json checkpoint_json FROM research_tasks t LEFT JOIN research_checkpoints c ON c.task_id=t.id WHERE t.id=?").bind(taskId).first();return{...row,checkpoint:row?.checkpoint_json?JSON.parse(row.checkpoint_json):null}}
  async recoverStaleRunningTasks(){const cutoff=new Date(Date.now()-15*60_000).toISOString(),now=isoNow(),result=await this.db.prepare("UPDATE research_tasks SET status='incomplete_retry',error_code='stale_running_lease_recovered',next_attempt_at=?,updated_at=? WHERE superseded_by_task_id IS NULL AND status='running' AND updated_at<?").bind(now,now,cutoff).run();return{recovered:Number(result?.meta?.changes??result?.changes??0),cutoff}}
