  async saveRequirements(jobId,input){const listing=await this.db.prepare("SELECT id FROM listing_versions WHERE canonical_job_id=? ORDER BY fetched_at DESC LIMIT 1").bind(jobId).first();if(!listing)throw new Error("listing_version_not_found");const evidence=await this.db.prepare("SELECT COUNT(*) n FROM evidence WHERE canonical_job_id=? AND listing_version_id=?").bind(jobId,listing.id).first();if(!Number(evidence?.n))throw new Error("listing_evidence_required");if(!Array.isArray(input.requirements)||!input.requirements.length)throw new Error("requirements_required");const now=isoNow(),allowed=new Set(['must_have','nice_to_have','implied']),statements=[],rows=input.requirements.map((x,i)=>{const kind=String(x?.requirement_kind||''),text=String(x?.requirement_text||'').trim(),anchor=String(x?.source_anchor||'').trim();if(!allowed.has(kind)||!text||!anchor)throw new Error(`invalid_requirement:${i}`);const row={id:uuid('requirement'),job_id:jobId,listing_version_id:listing.id,requirement_kind:kind,requirement_text:text,source_anchor:anchor,created_at:now};statements.push(this.db.prepare("INSERT INTO job_requirements(id,canonical_job_id,listing_version_id,requirement_kind,requirement_text,source_anchor,created_at) VALUES(?,?,?,?,?,?,?)").bind(row.id,jobId,listing.id,kind,text,anchor,now));return row});await this.db.batch(statements);return{job_id:jobId,listing_version_id:listing.id,requirements:rows}}
