  async assertListingFresh(jobId,phase='approval'){if(!['approval','submission'].includes(phase))throw new Error("invalid_freshness_phase");const row=await this.db.prepare("SELECT c.id,c.availability,c.captured_at,c.listing_version_id,c.capture_source,v.content_hash FROM authenticated_listing_checks c LEFT JOIN listing_versions v ON v.id=c.listing_version_id WHERE c.canonical_job_id=? AND c.capture_source='public_server_fetch' ORDER BY c.captured_at DESC LIMIT 1").bind(jobId).first();if(!row)throw new Error(`trusted_fresh_listing_check_required_before_${phase}`);if(row.availability!=='open')throw new Error(`listing_${row.availability}_blocks_${phase}`);if(Date.now()-Date.parse(row.captured_at)>LISTING_FRESHNESS_MINUTES*60_000)throw new Error(`fresh_listing_check_required_before_${phase}`);return{check_id:row.id,job_id:jobId,phase,availability:'open',captured_at:row.captured_at,listing_version_id:row.listing_version_id,content_hash:row.content_hash,capture_source:row.capture_source,fresh_for_minutes:LISTING_FRESHNESS_MINUTES}}
