function html() { return String.raw`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>True North Citadel</title><style>:root{color-scheme:dark;--ink:#edf2f7;--muted:#9fb0c1;--panel:#142334;--line:#29445d;--accent:#63d7c5;--warn:#ffca75}*{box-sizing:border-box}body{margin:0;background:#08131f;color:var(--ink);font:16px/1.5 system-ui}header,main{max-width:1180px;margin:auto;padding:20px}header{display:flex;justify-content:space-between;align-items:center}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px}.card{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:16px;overflow:auto}.muted{color:var(--muted)}.badge{color:var(--accent)}button,input,textarea,select{font:inherit;padding:9px;border-radius:7px;border:1px solid var(--line)}button{background:var(--accent);color:#06211c;font-weight:700}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid var(--line);padding:8px}.warn{color:var(--warn)}dialog{background:var(--panel);color:var(--ink);border:1px solid var(--line);border-radius:12px}label{display:block;margin:8px 0}@media(max-width:600px){header{align-items:flex-start;flex-direction:column}}</style><dialog id="login"><form method="dialog" id="loginForm"><h2>Private access</h2><label>Password <input name="password" type="password" required></label><button>Sign in</button><p id="loginError" class="warn"></p></form></dialog><header><div><h1>True North Citadel</h1><div class="muted">Private career operations</div></div><strong class="badge">Cleanup: preview only</strong></header><main><section class="grid"><article class="card"><h2>Coverage</h2><pre id="coverage">Loading…</pre></article><article class="card"><h2>Role profile</h2><form id="profile"><label>Name <input name="name" required></label><label>Title aliases <textarea name="aliases" rows="4"></textarea></label><label>Exclusions <textarea name="exclusions" rows="3"></textarea></label><label>Review threshold <input name="review_threshold" type="number"></label><button>Save new version</button></form></article></section><section class="card"><h2>Research queue</h2><label>Status filter <select id="statusFilter"><option value="">All</option><option>login_required</option><option>blocked</option><option>incomplete_retry</option><option>pending</option><option>complete</option></select></label><table><thead><tr><th>Source</th><th>Task</th><th>Status</th><th>URL / error</th></tr></thead><tbody id="queue"></tbody></table></section><section class="card"><h2>Researched jobs</h2><table><thead><tr><th>Role</th><th>Company</th><th>Source</th><th>Evidence</th></tr></thead><tbody id="jobs"></tbody></table></section></main><script>const byId=id=>document.getElementById(id),login=byId('login'),loginForm=byId('loginForm'),loginError=byId('loginError'),coverage=byId('coverage'),profile=byId('profile'),statusFilter=byId('statusFilter'),queue=byId('queue'),jobs=byId('jobs');const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(p,o){const r=await fetch(p,o);if(r.status===401){login.showModal();throw Error('auth')}if(!r.ok)throw Error(await r.text());return r.status===204?null:r.json()}async function load(){const [c,q,j,p]=await Promise.all([api('/api/coverage'),api('/api/queue'),api('/api/jobs'),api('/api/profile')]);coverage.textContent=JSON.stringify(c,null,2);queue.innerHTML=q.filter(x=>!statusFilter.value||x.status===statusFilter.value).map(x=>'<tr><td>'+esc(x.source)+'</td><td>'+esc(x.task_kind)+'</td><td>'+esc(x.status)+'</td><td><a href="'+esc(x.url)+'" rel="noreferrer">listing</a> '+esc(x.error_code||'')+'</td></tr>').join('');jobs.innerHTML=j.map(x=>'<tr><td>'+esc(x.title||'Unknown')+'</td><td>'+esc(x.company||'')+'</td><td>'+esc(x.source)+'</td><td>'+esc(x.evidence_count)+'</td></tr>').join('');for(const [k,v] of Object.entries(p)){const e=profile.elements[k];if(e)e.value=Array.isArray(v)?v.join('\n'):v}}loginForm.onsubmit=async e=>{e.preventDefault();const r=await fetch('/api/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({password:new FormData(e.target).get('password')})});if(r.ok){login.close();load()}else loginError.textContent='Sign-in failed'};profile.onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await api('/api/profile',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({id:'default',name:f.get('name'),aliases:String(f.get('aliases')).split(/\n+/).filter(Boolean),exclusions:String(f.get('exclusions')).split(/\n+/).filter(Boolean),review_threshold:Number(f.get('review_threshold'))})});load()};statusFilter.onchange=load;load().catch(()=>{});</script>`; }

